}

inline fun <reified T : Enum<T>> parse(s: String): T? =
    try {
        enumValueOf<T>(s)
    } catch (e: IllegalArgumentException) {
        null
    }

enum class Level { LOW, HIGH }

fun main() {
    println(parse<Level>("HIGH"))
    println(parse<Level>("high"))
}

interface Labelled { val label: String }

enum class Tab(override val label: String) : Labelled {
    HOME("Home"), SEARCH("Search"), PROFILE("Profile")
}

enum class Priority(val weight: Int) {
    HIGH(10), LOW(1), MEDIUM(5)
}

fun main() {
    val ps = listOf(Priority.MEDIUM, Priority.LOW, Priority.HIGH)
    println(ps.sorted())
    println(Priority.LOW < Priority.HIGH)
    println(ps.maxBy { it.ordinal }.weight)
}
